import {DEFAULTS,aggregate,nationalInputs,forecastRace,simulate,validatePoll,validateScenario,clamp} from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>`${Math.round(x*100)}%`,signed=x=>`${x>0?'+':''}${x.toFixed(1)}`;
const margin=(m,ind=false)=>`${m>=0?(ind?'I':'D'):'R'}+${Math.abs(m).toFixed(1)}`;
const officeNames={senate:'Senate',house:'House',governor:'Governors'};
const holdovers={senate:{D:34,R:31},house:{D:0,R:0},governor:{D:5,R:9}};
let data,map,office='senate',page='forecast',view='map',metric='probability',selected='senate-MI',filterState='',filter='all',query='',scenario=structuredClone(DEFAULTS),results,baseResults,baselineByOffice={},lastDataSnapshot,importType='scenario',timer,toastTimer;
let saved=[];try{saved=JSON.parse(localStorage.getItem('atlas-scenarios-v1')||'[]');if(!Array.isArray(saved))saved=[];}catch{}
const oldDate=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
const isChanged=()=>JSON.stringify(scenario)!==JSON.stringify(DEFAULTS);
function raceColor(r){if(!r)return '#303947';if(r.thirdProbability>0.5)return '#5b9d85';const p=r.probability;if(r.independent&&p>.5)return p>.8?'#3e8e77':'#82af9d';if(metric==='margin'){const m=r.margin;return Math.abs(m)<2?'#a5a1ac':m>0?m>15?'#345b9f':m>5?'#5483ca':'#93b3e1':m<-15?'#964b52':m<-5?'#c47177':'#dba7a8';}return p>.95?'#345b9f':p>.8?'#5483ca':p>.6?'#93b3e1':p>=.4?'#a5a1ac':p>.2?'#dba7a8':p>.05?'#c47177':'#964b52';}
const rating=r=>r.thirdProbability>.25?'Multi-candidate':r.probability>.95?'Safe '+(r.independent?'I':'D'):r.probability>.8?'Likely '+(r.independent?'I':'D'):r.probability>.6?'Lean '+(r.independent?'I':'D'):r.probability>=.4?'Toss-up':r.probability>.2?'Lean R':r.probability>.05?'Likely R':'Safe R';
function calculate(){
  const nat=nationalInputs(data,scenario),races=data.races.filter(r=>r.office===office).map(r=>forecastRace(r,data,scenario,nat));
  results=simulate(races,scenario,{office,holdovers:holdovers[office]});
  if(!baselineByOffice[office])baselineByOffice[office]=simulate(data.races.filter(r=>r.office===office).map(r=>forecastRace(r,data,structuredClone(DEFAULTS))),DEFAULTS,{office,holdovers:holdovers[office]});
  baseResults=baselineByOffice[office];
}
function rangeControl(key,label,min,max,step,value,left,right,help='',attrs=''){
  return `<div class="control"><div class="control-top"><label for="${key}">${label}</label><output class="value-chip" for="${key}" id="${key}-value">${formatControl(key,value)}</output></div><input id="${key}" data-control="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" ${attrs}><div class="range-labels"><span>${left}</span><span>${right}</span></div>${help?`<div class="control-help">${help}</div>`:''}</div>`;
}
function formatControl(key,value){return ['approval','pollWeight'].includes(key)?`${Math.round(value)}%`:key==='generic'?margin(value):key.includes('Sigma')?`${value.toFixed(1)} pp`:signed(value)+' pp';}
function render(){
  document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
  if(page==='method')return renderMethod();if(page==='sources')return renderSources();
  calculate();const nat=nationalInputs(data,scenario),polled=results.races.filter(r=>r.pollCount).length;
  $('#app').innerHTML=`<div class="hero"><div><div class="eyebrow">THE 2026 MIDTERMS / NOVEMBER 03</div><h1>Every race. Every possibility.</h1><p>A polling and fundamentals model. An election you can explore.</p></div><div class="hero-meta"><div><span class="status-dot"></span> INPUT SNAPSHOT <strong>${oldDate(data.asOf).toUpperCase()}</strong></div><div>4,000 SIMULATIONS <strong>· EXPERIMENTAL MODEL</strong></div></div></div>
  <div class="office-bar" role="tablist" aria-label="Election office">${Object.entries(officeNames).map(([k,v])=>`<button role="tab" aria-selected="${office===k}" class="office-tab ${office===k?'active':''}" data-office="${k}">${v}<span>${k==='senate'?35:k==='house'?435:36}</span></button>`).join('')}<span class="office-note">${office==='senate'?'51 D seats for control · R holds the tiebreak':office==='house'?'218 seats for a majority':'36 state elections · 14 holdovers'}</span></div>
  <div class="dashboard"><div class="content-column"><div id="summary"></div>
  <section class="panel"><div class="section-head"><h2>The ${office==='governor'?'governor':office} map <span id="map-subtitle">${office==='house'?'State overview':'Select a state to explore'}</span></h2><div class="map-options">${office==='house'?`<button data-view="map" class="${view==='map'?'active':''}">States</button><button data-view="tiles" class="${view==='tiles'?'active':''}">Districts</button>`:`<button data-metric="probability" class="${metric==='probability'?'active':''}">Win chance</button><button data-metric="margin" class="${metric==='margin'?'active':''}">Margin</button>`}</div></div><div class="map-area" id="map"></div><div class="map-caption" id="map-caption"></div><div class="map-footer"><div class="legend"><span class="legend-label">D</span>${['#345b9f','#5483ca','#93b3e1','#a5a1ac','#dba7a8','#c47177','#964b52'].map(c=>`<i style="background:${c}"></i>`).join('')}<span class="legend-label">R</span><span> · Gray: no election · Green: I</span></div><span class="map-instruction">CLICK A STATE TO EXPLORE ↗</span></div><div id="selection"></div></section>
  <div class="coverage"><span>◈</span><span id="coverage-text">Curated snapshot: ${polled} of ${results.races.length} races have polling. Other races use fundamentals; this is not a live polling feed.</span><button data-page="sources">Inspect inputs ↗</button></div>
  <section class="panel"><div class="section-head"><h2>The range of outcomes</h2><span class="threshold-label">80% INTERVAL · <span id="interval"></span> D ${office==='governor'?'GOVERNORS':'SEATS'}</span></div><div class="distribution" id="histogram" aria-label="Simulated Democratic seat distribution" role="img"></div><div class="distribution-axis" id="hist-axis"></div></section>
  <section class="panel"><div class="section-head"><h2>Race explorer <span id="race-count"></span></h2><button class="button small ghost" id="download-forecast">↓ Export forecast</button></div><div class="race-toolbar"><input class="search" id="search" placeholder="Search ${office==='house'?'district or state':'state'}…" aria-label="Search races" value="${esc(query)}"><select id="state-filter" aria-label="Filter races by state"><option value="">All states</option>${data.states.filter(s=>results.races.some(r=>r.state===s.abbr)).map(s=>`<option value="${s.abbr}" ${filterState===s.abbr?'selected':''}>${esc(s.name)}</option>`).join('')}</select><select id="race-filter" aria-label="Filter races"><option value="all" ${filter==='all'?'selected':''}>All races</option><option value="competitive" ${filter==='competitive'?'selected':''}>Competitive</option><option value="polled" ${filter==='polled'?'selected':''}>With polling</option><option value="changed" ${filter==='changed'?'selected':''}>Changed winner</option></select></div><div class="table-scroll"><table class="race-table"><thead><tr><th>RACE ↕</th><th>PROJECTED D−R</th><th>D / I WIN CHANCE</th><th>INPUTS</th><th>RATING</th></tr></thead><tbody id="race-rows"></tbody></table></div><div class="table-foot"><span>Sorted by competitiveness · positive adjustments favor D (I in independent Senate races).</span><span id="table-total"></span></div></section></div>
  <aside class="panel workbench" aria-label="Scenario controls"><div class="workbench-head"><div class="eyebrow">MAKE IT YOURS</div><h2>Scenario workbench</h2><p>Move the assumptions. Watch the map respond.</p><div class="scenario-badge" id="scenario-badge"></div></div>
  <div class="controls">${rangeControl('nationalError','National polling error',-15,15,.5,scenario.nationalError,'R +15','D +15','Adds directly to every modeled race margin.')}${rangeControl('generic','Generic ballot',-20,20,.5,nat.generic,'R +20','D +20','Changes the fundamentals prior. Strongly polled races move less.')}${rangeControl('approval','Presidential approval',10,90,1,nat.approval,'10% approval','90% approval','Higher Republican presidential approval favors R in the prior.')}</div>
  <div class="workbench-section"><div class="label">STATE ADJUSTMENT <span id="state-chip"></span></div><select class="select" id="state-control" aria-label="Choose state to adjust">${data.states.filter(s=>results.races.some(r=>r.state===s.abbr)).map(s=>`<option value="${s.abbr}">${esc(s.name)}</option>`).join('')}</select><div id="state-slider"></div><p class="control-help">Applies to every race in this state across all three offices. Added after the polling / fundamentals blend.</p></div>
  <div class="workbench-section"><details id="advanced"><summary>Model weights & uncertainty</summary>${rangeControl('pollWeight','Polling influence',0,200,5,scenario.pollWeight,'Fundamentals only','2× evidence')}${rangeControl('incumbency','Incumbency advantage',0,6,.5,scenario.incumbency,'0 pp','6 pp','Applied only to verified returning Senate / governor incumbents. House bonus disabled pending a candidate roster.')}${rangeControl('nationalSigma','National uncertainty',0,8,.5,scenario.nationalSigma,'0 pp','8 pp')}${rangeControl('stateSigma','State uncertainty',0,8,.5,scenario.stateSigma,'0 pp','8 pp')}${rangeControl('localSigma','Race uncertainty floor',.5,10,.5,scenario.localSigma,'0.5 pp','10 pp')}<label class="control-help" for="caucus">Independent Senate winners</label><select class="select" id="caucus"><option value="other" ${scenario.neCaucus==='other'?'selected':''}>Remain independent (default)</option><option value="D" ${scenario.neCaucus==='D'?'selected':''}>Hypothetical: join D caucus</option></select><p class="control-help">NE, MT and SD independent challengers are never automatically counted as Democrats. The 50–50 Senate tiebreak goes to R.</p></details></div>
  <div class="workbench-section"><div class="actions"><button class="button primary" id="save-scenario">＋ Save scenario</button><button class="button" id="share-scenario">↗ Share</button></div><button class="reset" id="reset-scenario">↺ Reset to baseline</button><button class="reset" id="open-scenarios">Saved scenarios & import / export</button></div></aside></div>`;
  bindForecast();updateVisuals();
}
function summary(){
  const total=office==='house'?435:office==='senate'?100:50,other=results.otherMean,r=total-results.mean-other;
  const change=results.mean-baseResults.mean;
  const odds=office==='governor'?`${results.mean.toFixed(1)}<span class="small"> / 50</span>`:pct(results.control);
  const seats=office==='governor'?`${r.toFixed(1)}<span class="small"> R</span>`:`${results.mean.toFixed(1)}<span class="small"> D / ${r.toFixed(1)} R</span>`;
  $('#summary').innerHTML=`<section class="summary" aria-live="polite"><div class="metric"><div class="label">${office==='governor'?'Expected D governors':'Democratic control'}</div><div class="metric-value blue">${odds}</div><div class="metric-note">${office==='governor'?'Includes 5 D and 9 R holdovers':`R control <span class="red">${pct(results.rcontrol)}</span>${results.unresolved>.001?' · unresolved '+pct(results.unresolved):''}`}</div></div><div class="metric"><div class="label">${office==='governor'?'Expected R governors':'Expected seat count'}</div><div class="metric-value">${seats}</div><div class="seatbar"><span class="dem" style="width:${results.mean/total*100}%"></span>${other>.001?`<span class="ind" style="width:${other/total*100}%"></span>`:''}<span class="rep" style="width:${r/total*100}%"></span></div><div class="metric-note">${other>.01?`${other.toFixed(1)} independent · `:''}${Math.abs(change)<.05?'Baseline scenario':`${signed(change)} D ${office==='governor'?'governors':'seats'} vs. baseline`}</div></div><div class="metric"><div class="label">Competitive races</div><div class="metric-value">${results.races.filter(r=>Math.max(r.probability,1-r.probability-r.thirdProbability)<.8).length}<span class="small"> / ${results.races.length}</span></div><div class="metric-note">No candidate above 80% win chance</div></div></section>`;
  $('#scenario-badge').innerHTML=`<i></i>${isChanged()?'CUSTOM SCENARIO · UNSAVED CHANGES':'BASELINE · SOURCED INPUT SNAPSHOT'}`;
}
function updateVisuals(){summary();renderMap();renderSelection();renderHistogram();renderTable();syncStateControl();$('#interval').textContent=`${results.low}–${results.high}`;}
function renderMap(){
  if(office==='house'&&view==='tiles'){
    $('#map').innerHTML=`<div class="tile-map">${data.states.filter(s=>results.races.some(r=>r.state===s.abbr)).map(s=>`<div class="tile-group"><span class="tile-state">${s.abbr}</span><div class="tile-set">${results.races.filter(r=>r.state===s.abbr).map(r=>`<button data-race="${r.id}" class="tile ${r.id===selected?'selected':''}" style="background:${raceColor(r)}" title="${r.name}: ${margin(r.margin)} · D ${pct(r.probability)}" aria-label="${r.name}, Democratic win chance ${pct(r.probability)}"></button>`).join('')}</div></div>`).join('')}</div>`;
    $('#map-caption').textContent='One square per congressional district, grouped by state. Tile positions are not district geography.';return;
  }
  const currentState=results.races.find(r=>r.id===selected)?.state;
  $('#map').innerHTML=`<svg class="us-map" viewBox="0 0 975 610" role="group" aria-label="Interactive ${officeNames[office]} election map">${map.map(s=>{
    const rs=results.races.filter(r=>r.state===s.abbr);const race=office==='house'&&rs.length?{probability:rs.reduce((n,r)=>n+r.probability,0)/rs.length,margin:rs.reduce((n,r)=>n+r.margin,0)/rs.length}:rs[0];
    const label=race?`${s.name}: ${office==='house'?`${rs.length} districts, expected D seats ${rs.reduce((n,r)=>n+r.probability,0).toFixed(1)}`:`${margin(race.margin,race.independent)}, ${race.independent?'I':'D'} win chance ${pct(race.probability)}`}`:`${s.name}: no ${office} election`;
    return `<path d="${s.path}" fill="${raceColor(race)}" data-state="${s.abbr}" class="${currentState===s.abbr?'selected':''}" tabindex="0" role="button" aria-label="${esc(label)}"><title>${esc(label)}</title></path>`;
  }).join('')}${map.filter(s=>s.abbr!=='DC').map(s=>`<text x="${s.centroid[0]}" y="${s.centroid[1]+3}" text-anchor="middle">${s.abbr}</text>`).join('')}</svg>`;
  $('#map-caption').textContent=office==='house'?'State colors show average district D win probability, not the chance of winning a statewide contest. Switch to Districts for all 435 seats.':metric==='probability'?'Color encodes win probability, including shared national and state uncertainty. Gray states are not voting for this office.':'Color encodes the projected Democratic-minus-Republican margin. Independent Senate races use I-minus-R.';
}
function renderSelection(){
  const r=results.races.find(r=>r.id===selected)||results.races[0];selected=r.id;const baseline=baseResults.races.find(b=>b.id===r.id);
  const win=r.independent?'I':'D';
  $('#selection').innerHTML=`<div class="selection-detail"><div><div class="selection-title">${esc(r.name)}${r.special?' <span class="year">SPECIAL</span>':''}</div><div class="selection-subtitle">${r.incumbentParty==='I'?'Independent':r.incumbentParty==='D'?'Democratic':'Republican'}-held · ${r.pollCount?`${r.pollCount} sourced poll${r.pollCount>1?'s':''}`:'Fundamentals only'}${r.incumbentRunning===false?' · no incumbency bonus':''}</div><div class="detail-metrics"><div><span>PROJECTED ${r.independent?'I−R':'D−R'}</span><strong class="${r.margin>=0?(r.independent?'green':'blue'):'red'}">${margin(r.margin,r.independent)}</strong></div><div><span>${win} WIN CHANCE</span><strong>${pct(r.probability)}</strong></div><div><span>BASELINE</span><strong>${margin(baseline.margin,r.independent)}</strong></div></div>${r.thirdProbability?`<p class="selected-note green">Third-candidate win chance: ${pct(r.thirdProbability)} · R ${pct(1-r.probability-r.thirdProbability)}. Three-candidate approximation, not a ranked-choice model.</p>`:''}</div><div class="detail-control">${rangeControl('raceError','This race only',-20,20,.5,scenario.races[r.id]??0,'R +20',`${win} +20`)}<div class="selected-note">Polling average: ${r.pollAverage==null?'No qualifying polls':margin(r.pollAverage,r.independent)} · Prior: ${margin(r.prior,r.independent)} · Polling blend: ${Math.round(r.pollWeight*100)}%${r.note?'<br>'+esc(r.note):''}</div></div></div>`;
}
function syncStateControl(){const st=results.races.find(r=>r.id===selected)?.state||'MI';$('#state-control').value=st;$('#state-chip').textContent=st;$('#state-slider').innerHTML=rangeControl('stateError','State polling error',-20,20,.5,scenario.states[st]??0,'R +20','D / I +20');}
function renderHistogram(){
  const values=Object.keys(results.histogram).map(Number),min=Math.min(...values),max=Math.max(...values),peak=Math.max(...Object.values(results.histogram));
  const binWidth=office==='house'?Math.max(1,Math.ceil((max-min)/60)):1,bins=[];for(let n=min;n<=max;n+=binWidth){let v=0;for(let j=0;j<binWidth;j++)v+=results.histogram[n+j]||0;bins.push({n,v});}const bpeak=Math.max(...bins.map(b=>b.v));
  const majority=office==='senate'?51:office==='house'?218:25;
  $('#histogram').innerHTML=bins.map(({n,v})=>`<div class="hist-bar ${n>=majority?'dem':'rep'}" style="height:${Math.max(1,v/bpeak*100)}%" data-tip="${n}${binWidth>1?'–'+(n+binWidth-1):''} D: ${pct(v/results.runs)}"></div>`).join('');
  $('#histogram').setAttribute('aria-label',`Democratic count: median ${results.median}, 80 percent interval ${results.low} to ${results.high}. ${office==='governor'?'':`${majority} needed for control.`}`);
  $('#hist-axis').innerHTML=`<span>${min} D</span><span>MEDIAN ${results.median} · ${office==='governor'?'D GOVERNORSHIPS':majority+' D FOR CONTROL'}</span><span>${max} D</span>`;
}
function renderTable(){
  const baseline=new Map(baseResults.races.map(r=>[r.id,r]));
  let rs=results.races.filter(r=>(!filterState||r.state===filterState)&&(!query||`${r.name} ${data.states.find(s=>s.abbr===r.state)?.name}`.toLowerCase().includes(query.toLowerCase())));
  if(filter==='competitive')rs=rs.filter(r=>Math.max(r.probability,1-r.probability-r.thirdProbability)<.8);
  if(filter==='polled')rs=rs.filter(r=>r.pollCount);if(filter==='changed')rs=rs.filter(r=>(r.margin>0)!==(baseline.get(r.id).margin>0));
  rs.sort((a,b)=>Math.abs(a.probability-.5)-Math.abs(b.probability-.5)||a.name.localeCompare(b.name));
  $('#race-rows').innerHTML=rs.length?rs.map(r=>`<tr data-race="${r.id}" tabindex="0" class="${selected===r.id?'selected':''}" aria-label="Explore ${esc(r.name)}"><td class="race-name">${esc(r.name)}<small>${r.independent?'I vs. R':r.special?'Special election':r.office==='house'?r.incumbentParty+' reference incumbent':r.incumbentParty+'-held'}${r.offset?' · adjusted':''}</small></td><td class="margin ${r.margin>=0?(r.independent?'green':'blue'):'red'}">${margin(r.margin,r.independent)}${r.thirdProbability>.01?' *':''}</td><td><div class="probability"><span class="margin">${r.independent?'I ':''}${pct(r.probability)}</span><span class="prob-track"><i style="width:${r.probability*100}%"></i></span></div></td><td><span class="margin" style="color:var(--muted)">${r.pollCount?r.pollCount+' poll'+(r.pollCount>1?'s':''):'Prior only'}</span></td><td><span class="rating ${rating(r)==='Toss-up'?'tossup':''}">${rating(r)}</span></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No races match these filters.</td></tr>';
  $('#race-count').textContent=`${rs.length} races`;$('#table-total').textContent=`${rs.length} / ${results.races.length}`;
}
function updateModel(){calculate();const advancedOpen=$('#advanced')?.open;updateVisuals();if(advancedOpen&&$('#advanced'))$('#advanced').open=true;}
function scheduleUpdate(){clearTimeout(timer);timer=setTimeout(updateModel,65);}
function bindForecast(){
  $('#app').addEventListener('input',onForecastInput);
  $('#search').addEventListener('input',e=>{query=e.target.value;renderTable();});
  $('#state-filter').addEventListener('change',e=>{filterState=e.target.value;renderTable();});
  $('#race-filter').addEventListener('change',e=>{filter=e.target.value;renderTable();});
  $('#state-control').addEventListener('change',e=>{const r=results.races.find(r=>r.state===e.target.value);if(r){selected=r.id;updateVisuals();}else notify('No '+officeNames[office]+' race in that state.');});
  $('#caucus').addEventListener('change',e=>{scenario.neCaucus=e.target.value;updateModel();});
  $('#save-scenario').onclick=saveScenario;$('#share-scenario').onclick=shareScenario;$('#reset-scenario').onclick=()=>{scenario=structuredClone(DEFAULTS);history.replaceState(null,'',location.pathname+location.search);render();notify('Baseline restored.');};$('#open-scenarios').onclick=openScenarios;
  $('#download-forecast').onclick=()=>{const rows=[['race','office','state','projected_left_minus_R','left_party','left_win_probability','independent_third_win_probability','poll_count','poll_weight','prior','local_adjustment','snapshot_date'],...results.races.map(r=>[r.name,r.office,r.state,r.margin.toFixed(3),r.independent?'I':'D',r.probability,r.thirdProbability,r.pollCount,r.pollWeight.toFixed(3),r.prior.toFixed(3),r.offset,data.asOf])];download('midterm-atlas-'+office+'-forecast.csv',rows.map(r=>r.join(',')).join('\n'),'text/csv');};
}
function onForecastInput(e){const k=e.target.dataset.control;if(!k)return;const val=Number(e.target.value);$('#'+k+'-value').textContent=formatControl(k,val);if(k==='raceError')scenario.races[selected]=val;else if(k==='stateError'){const state=results.races.find(r=>r.id===selected).state;scenario.states[state]=val;}else scenario[k]=val;scheduleUpdate();}
// Delegated controls survive map/table/detail redraws.
$('#app').addEventListener('click',e=>{
  const officeButton=e.target.closest('[data-office]');if(officeButton){office=officeButton.dataset.office;selected=data.races.find(r=>r.office===office&&r.state==='MI').id;filterState='';query='';filter='all';render();return;}
  const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render();window.scrollTo({top:0});return;}
  const m=e.target.closest('[data-metric]');if(m){metric=m.dataset.metric;render();return;}
  const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;render();return;}
  const r=e.target.closest('[data-race]');if(r){selected=r.dataset.race;updateVisuals();return;}
  const s=e.target.closest('[data-state]');if(s){const races=results.races.filter(r=>r.state===s.dataset.state);if(!races.length){notify('No '+officeNames[office]+' election in this state.');return;}selected=races.sort((a,b)=>Math.abs(a.margin)-Math.abs(b.margin))[0].id;if(office==='house')filterState=s.dataset.state;updateVisuals();}
});
$('#app').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-state],[data-race]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.querySelectorAll('header [data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo({top:0});});$('.brand').onclick=e=>{e.preventDefault();page='forecast';render();};
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function saveScenario(){const name=prompt('Name this scenario',`Scenario ${saved.length+1}`);if(!name?.trim())return;saved.push({name:name.trim().slice(0,80),scenario:structuredClone(scenario),office,created:new Date().toISOString(),dataVersion:data.version});saved=saved.slice(-30);try{localStorage.setItem('atlas-scenarios-v1',JSON.stringify(saved));notify('Scenario saved in this browser.');}catch{notify('Browser storage is unavailable. Export your scenario instead.');}}
async function shareScenario(){
  const payload={scenario,office,dataVersion:data.version};const encoded=btoa(unescape(encodeURIComponent(JSON.stringify(payload))));const url=new URL(location.href);url.hash='scenario='+encoded;
  history.replaceState(null,'',url);try{await navigator.clipboard.writeText(url.href);notify('Scenario link copied. Custom polling imports are not included.');}catch{prompt('Copy this scenario link. Custom polling imports are not included:',url.href);}
}
function openScenarios(){const dialog=$('#scenario-dialog');$('#scenario-list').innerHTML=saved.length?saved.map((s,i)=>`<div class="saved-item"><span>${esc(s.name)}</span><div><button class="button small" data-load="${i}">Load</button><button class="button small ghost" data-delete="${i}" aria-label="Delete ${esc(s.name)}">×</button></div></div>`).join(''):'<p class="empty">Save a scenario to compare it later.<br>Scenarios are stored on this device.</p>';if(!dialog.open)dialog.showModal();}
$('#scenario-list').onclick=e=>{const load=e.target.closest('[data-load]'),del=e.target.closest('[data-delete]');if(load){const s=saved[Number(load.dataset.load)];try{scenario=validateScenario(s.scenario,data);office=s.office in officeNames?s.office:'senate';selected=data.races.find(r=>r.office===office).id;$('#scenario-dialog').close();page='forecast';render();notify('Scenario loaded.');}catch(err){notify(err.message);}}if(del){saved.splice(Number(del.dataset.delete),1);try{localStorage.setItem('atlas-scenarios-v1',JSON.stringify(saved));}catch{}openScenarios();}};
$('#export-scenario').onclick=()=>download('midterm-atlas-scenario.json',JSON.stringify({scenario,office,dataVersion:data.version},null,2));$('#import-scenario').onclick=()=>{importType='scenario';$('#file-input').click();};
$('#file-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>3_000_000)throw Error('Choose a JSON file smaller than 3 MB.');const raw=JSON.parse(await file.text());if(importType==='scenario'){scenario=validateScenario(raw.scenario??raw,data);if(raw.office in officeNames)office=raw.office;selected=data.races.find(r=>r.office===office).id;$('#scenario-dialog').close();page='forecast';render();notify('Scenario imported.');}else{const rows=Array.isArray(raw)?raw:raw.polls;if(!Array.isArray(rows)||!rows.length||rows.length>10000)throw Error('Expected 1–10,000 polling rows.');const ids=new Set(data.races.map(r=>r.id));rows.forEach((p,i)=>{const errors=validatePoll(p,ids);if(errors.length)throw Error(`Row ${i+1}: ${errors.join(', ')}`);if(p.end>data.asOf)throw Error(`Row ${i+1}: poll ends after the snapshot date. Edit snapshot asOf in source for a new dated release.`);});const byId=new Map(data.polls.map(p=>[p.id,p]));for(const p of rows)byId.set(p.id,p);const dedup=new Set();data.polls=[...byId.values()].filter(p=>{const k=p.raceId+'|'+p.pollster.toLowerCase().split('/')[0].trim()+'|'+p.end;if(dedup.has(k))return false;dedup.add(k);return true;});baselineByOffice={};render();notify(`${rows.length} polling rows imported for this session. Export to preserve them.`);}}catch(err){notify(err.message);} };
function renderMethod(){
 $('#app').innerHTML=`<article class="page-content"><div class="eyebrow">OPEN THE BLACK BOX</div><h1>A model you can take apart.</h1><p class="intro">Midterm Atlas blends a partisan baseline, national conditions, incumbency and race polling. Then it simulates correlated election outcomes. This is an experimental, hand-specified model: its coefficients and probabilities have not been fitted or backtested. Treat it as a scenario laboratory, not a calibrated professional forecast.</p><div class="method-grid">
 <section class="method-card"><div class="eyebrow">01 / FUNDAMENTALS</div><h2>Start with a prior.</h2><p>State lean is the 2024 presidential D−R margin minus the national D−R margin (${data.national2024Margin.toFixed(2)} pp). House lean uses The Downballot’s rounded presidential margin on 2026 district lines.</p><div class="formula">National environment =<br>0.8 × generic D−R<br>+ 0.2 × 0.3 × (50 − approval)<br><br>Prior = lean + environment + incumbency</div><p>Governors receive 65% of the national environment effect. Verified returning Senate and governor incumbents get a configurable 2 pp bonus. House incumbency is disabled because the baseline’s reference officeholders do not establish who is running. Candidate quality, fundraising, economic indicators, redistricting litigation and demographics beyond partisan lean are not independently modeled.</p></section>
 <section class="method-card"><div class="eyebrow">02 / POLLING</div><h2>Weight evidence, then blend.</h2><p>Poll weights decay with a 14-day half-life and exclude polls more than 120 days old. Sample weight is √(min(n,1500)/800). If the effective sample is unknown, published margin of error gives a rough 3/MOE weight instead. LV/RV/adult factors are 1/.85/.6. One pollster is capped at one full weighted equivalent per race.</p><div class="formula">w = poll evidence / (poll evidence + 25/64)<br>Margin = w × polling + (1−w) × prior<br>+ national error + state error + race error</div><p>The 64 pp² prior variance and 25 pp² poll variance are modeling choices, not fitted parameters. We do not apply unverified pollster-quality ratings or house effects. Generic ballot and approval are correlated; the fixed blend limits but does not statistically eliminate double-counting.</p></section>
 <section class="method-card"><div class="eyebrow">03 / SIMULATIONS</div><h2>Errors travel together.</h2><p>Each of 4,000 deterministic Monte Carlo trials draws one national error shared by all races, a state error shared within each state, and independent race error. Defaults: national σ 2.5 pp, state σ 1.5 pp, local σ √(3² + 16 × (1−w)). More reliance on fundamentals increases uncertainty.</p><p>The fixed random seed lets you compare slider changes without random jumps. The reported 80% interval covers the 10th–90th percentiles. Cross-office national uncertainty uses the same conceptual structure; the dashboard simulates the selected office, not a joint three-office forecast. Normal tails and hand-specified variances may understate unusual outcomes.</p></section>
 <section class="method-card"><div class="eyebrow">04 / CONTROL & INDEPENDENTS</div><h2>Count the actual seats.</h2><p>Senate: 35 contests + 34 D-caucus and 31 R holdovers. Democratic control requires 51; Republican control requires 50 because the Republican vice president breaks a 50–50 tie. Outcomes where independent affiliation prevents an outright majority are labeled unresolved. House control requires 218 of 435. Governors include 5 D and 9 R holdovers; territories are excluded.</p><p>NE, MT and SD independent Senate challengers are counted as independent unless you choose the hypothetical D-caucus setting. Their unpolled priors use partisan lean as an imperfect proxy. Significant third candidates (≥10% in the imported polling average) are modeled separately by normalizing the available D/R/I shares and adding independent share uncertainty of 3 pp. Rhode Island is included this way. This is a simple plurality approximation; ranked-choice rounds, Louisiana runoffs, minor candidates and complex Alaska fields are not modeled. CA-03’s independent reference incumbent is not treated as a verified independent nominee.</p></section>
 <section class="method-card wide"><div class="eyebrow">05 / YOUR ASSUMPTIONS</div><h2>A polling miss, or a different electorate?</h2><p>The national, state and race error sliders are additive percentage-point adjustments after the blend. They express a hypothetical correction to the forecast margin. They are not random draws or changes to vote share. The generic ballot and approval sliders change the fundamentals prior; races with strong polling will respond less. State adjustments apply across Senate, House and governors. Saved and shared scenarios contain assumptions only, not custom polling imports.</p><p>Inputs are a curated, dated snapshot rather than an exhaustive polling feed. Each poll links to its original release and retains population/sample caveats. New data can be imported as normalized JSON, or maintained in the versioned source dataset. No paid polling API or unattended scraper is silently configured. Exported files retain dates so you can reproduce a run.</p></section></div><button class="button primary" data-page="forecast">Back to the map ↗</button></article>`;
}
function renderSources(){
 const national=nationalInputs(data,scenario),racesWith=new Set(data.polls.filter(p=>!['generic','approval'].includes(p.raceId)).map(p=>p.raceId));
 $('#app').innerHTML=`<article class="page-content"><div class="eyebrow">THE EVIDENCE</div><h1>Every input has a source.</h1><p class="intro">Snapshot dated ${oldDate(data.asOf)} · ${data.polls.length} polling rows · ${racesWith.size} of 506 races have race polling. The remaining races use fundamentals. This is a curated collection, not an exhaustive or automatically refreshed aggregate. ${data.polls.length!==lastDataSnapshot.polls.length?'Custom session inputs are active.':''}</p><div class="coverage"><span>◈</span><span>House polling coverage is limited. Its 435 race projections are primarily partisan-prior estimates. Probabilities are experimental and not backtested.</span></div>
 <div class="source-cards">${data.sources.map(s=>`<div class="source-card"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><p>${esc(s.note)}</p></div>`).join('')}</div>
 <section class="method-card"><h2>Update or inspect the inputs</h2><p>Download the current dataset, edit or add polls in the example schema, and import them here. Imports are validated, merged by id, and duplicate pollster / race / end-date entries are removed. They last for this session only. Polls after the snapshot date are rejected; a new dated source release requires updating <code>asOf</code> in the project. Candidate matchups should be checked against the linked release before adding a poll; the model does not infer nominee eligibility.</p><div class="source-controls"><button class="button primary" id="import-polls">↑ Import polling JSON</button><button class="button" id="export-data">↓ Full dataset</button><button class="button" id="example-polls">↓ Example schema</button><button class="button ghost" id="restore-data">Restore snapshot</button></div><p>Poll dates are field dates, not publication dates. Marist’s full RV sample is retained in notes and not treated as the LV effective sample. Pollster sponsor variants are normalized where known. Source releases occasionally contain different nominee names or matchup versions; party-level snapshots are shown without claiming a certified candidate roster.</p></section>
 <div class="section-head" style="padding:26px 0 10px"><h2>Polling ledger <span>${data.polls.length} rows</span></h2><select class="select" id="poll-filter" aria-label="Filter polling ledger" style="width:auto;margin:0"><option value="all">All polls</option><option value="senate">Senate</option><option value="house">House</option><option value="governor">Governors</option><option value="national">National</option></select></div><div class="poll-list" id="poll-list"></div></article>`;
 $('#import-polls').onclick=()=>{importType='polls';$('#file-input').click();};$('#export-data').onclick=()=>download('midterm-atlas-inputs.json',JSON.stringify(data,null,2));$('#example-polls').onclick=()=>download('polling-import-example.json',JSON.stringify([data.polls.find(p=>p.raceId==='senate-MI')],null,2));$('#restore-data').onclick=()=>{data=structuredClone(lastDataSnapshot);baselineByOffice={};renderSources();notify('Original snapshot restored.');};$('#poll-filter').onchange=e=>renderPollLedger(e.target.value);renderPollLedger('all');
}
function renderPollLedger(filter){
 const ps=data.polls.filter(p=>filter==='all'||(filter==='national'?['generic','approval'].includes(p.raceId):p.raceId.startsWith(filter+'-'))).sort((a,b)=>b.end.localeCompare(a.end)||a.raceId.localeCompare(b.raceId));
 $('#poll-list').innerHTML=ps.length?ps.map(p=>`<div class="poll-card"><div class="poll-card-head"><strong>${esc(p.raceId.replace('senate-','Senate · ').replace('governor-','Governor · ').replace('house-','House · ').replace('generic','National · generic ballot').replace('approval','National · presidential approval'))}</strong><span class="margin ${p.raceId==='approval'?'':((p.independent??p.dem)-p.rep>=0?'blue':'red')}">${p.raceId==='approval'?`${p.approve}% approve / ${p.disapprove}% disapprove`:`${p.independent!=null?'I '+p.independent:'D '+p.dem}% / R ${p.rep}%${p.other?' / I '+p.other+'%':''}`}</span></div><div class="poll-meta">${esc(p.pollster)} · ${p.start?oldDate(p.start)+' – ':''}${oldDate(p.end)} · ${esc(p.population)} · ${p.n?'n = '+p.n:p.fullSample?'full RV n = '+p.fullSample+'; effective LV n unknown':'effective n not published'}${p.moe?' · reported error ±'+p.moe+' pp':''}</div>${p.notes?`<p>${esc(p.notes)}</p>`:''}<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Original pollster release ↗</a></div>`).join(''):'<div class="empty">No polling rows for this filter.</div>';
}
try{
 const responses=await Promise.all([fetch('data.json'),fetch('map.json')]);if(responses.some(r=>!r.ok))throw Error('Could not load the input files.');[data,map]=await Promise.all(responses.map(r=>r.json()));lastDataSnapshot=structuredClone(data);
 const ids=new Set(data.races.map(r=>r.id));for(const p of data.polls){const errors=validatePoll(p,ids);if(errors.length)throw Error(`Dataset error (${p.id}): ${errors.join(', ')}`);}
 if(location.hash.startsWith('#scenario=')){try{const raw=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(10)))));scenario=validateScenario(raw.scenario,data);if(raw.office in officeNames)office=raw.office;selected=data.races.find(r=>r.office===office).id;}catch{notify('Could not read the shared scenario. Showing baseline.');}}
 render();
}catch(err){$('#app').innerHTML=`<div class="error-box"><h1>The forecast could not load.</h1><p>${esc(err.message)}</p><p>Serve the project through an HTTP server, then reload.</p></div>`;console.error(err);}
